  typeAnalyzer: TypeAnalyzer) extends Walker {
val errors = new ArrayList[StaticError]()
var analyzer = typeAnalyzer

def check() = {
  walk(compilation_unit.ast)
  errors
}

private def error(s:String, n:Node) = errors.add(TypeError.make(s,n))

private val sizeArithmetic =
  "Arithmetic on nat static arguments is not supported by the type checker; use a nat parameter or a literal."

private def hasSizeArithmetic(sarg: StaticArg) = sarg match {
  case SIntArg(_, _, _: IntBinaryOp) => true
  case _ => false
}

private val nn32Max = java.math.BigInteger.valueOf(4294967295L)
private val zz32Min = java.math.BigInteger.valueOf(Int.MinValue.toLong)
private val zz32Max = java.math.BigInteger.valueOf(Int.MaxValue.toLong)

// A literal size outside the values of every kind its parameters have: a nat parameter
// is an NN32 value and an int parameter a ZZ32 value.  No kinds known means either.
private def sizeOutOfRange(sarg: StaticArg, kinds: List[StaticParamKind]): Option[String] =
  sarg match {
    case SIntArg(_, _, SIntBase(_, _, lit)) =>
      val v = lit.getIntVal
      val nat = kinds.exists(_.isInstanceOf[KindNat])
      val int = kinds.exists(_.isInstanceOf[KindInt])
      val fitsNat = v.signum >= 0 && v.compareTo(nn32Max) <= 0
      val fitsInt = v.compareTo(zz32Min) >= 0 && v.compareTo(zz32Max) <= 0
      if ((nat && fitsNat) || (int && fitsInt) || (!nat && !int && (fitsNat || fitsInt))) None
      else if (nat && !int)
        Some("The static argument " + v + " is out of range for a nat parameter, whose values are those of NN32, 0 to 4294967295.")
      else if (int && !nat)
        Some("The static argument " + v + " is out of range for an int parameter, whose values are those of ZZ32, -2147483648 to 2147483647.")
      else
        Some("The static argument " + v + " is out of range for a nat parameter, whose values are those of NN32, and for an int parameter, whose values are those of ZZ32.")
    case _ => None
  }

// The kinds of the static parameters at each position, from the declared schemas of a
// checked reference; before type checking a reference has none, and its sizes wait.
private def kindsAt(schemas: List[Type], n: Int): Option[List[List[StaticParamKind]]] = {
  val lists = schemas.map(t => toListFromImmutable(t.getInfo.getStaticParams)).filter(_.size == n)
  if (lists.isEmpty) None else Some(List.tabulate(n)(i => lists.map(_(i).getKind)))
}

private def walkStaticArgs(sargs: List[StaticArg], kinds: Option[List[List[StaticParamKind]]]) =
  sargs.zipWithIndex.foreach {
    case (a: IntArg, i) =>
      if (hasSizeArithmetic(a))
        error("Ill-formed static argument: " + a + "\n    " + sizeArithmetic, a)
      kinds.foreach(ks => sizeOutOfRange(a, ks(i)).foreach(m =>
        error("Ill-formed static argument: " + a + "\n    " + m, a)))
    case (a, _) => walk(a)
  }

private def getTypes(typ:Id) = {
  val types = typ match {
    case SId(info,Some(name),text) =>
    globalEnv.api(name).typeConses.get(SId(info,None,text))
    case _ => compilation_unit.typeConses.get(typ)
  }
  if (types == null) error("Unknown type: " + typ, typ)
  types
}

override def walk(node:Any):Any = {

return i.accept(new NodeAbstractVisitor<FType>() {
    private long longify(IntExpr ie) {
	FType t = ie.accept(this);
	if (!(t instanceof IntNat)) {
	    error(ie, errorMsg("IntExpr ", ie, " evaluated to ", t, " (instead of IntNat)"));
	}
	return ((IntNat) t).getValue();
    }

    public FType forIntBase(IntBase n) {
	java.math.BigInteger v = n.getIntVal().getIntVal();
	if (v.bitLength() > 63) {
	    return error(n, errorMsg("Static argument ", v, " is out of range for a nat parameter, whose values are those of NN32, 0 to 4294967295, and for an int parameter, whose values are those of ZZ32, -2147483648 to 2147483647"));
	}
	return IntNat.make(v.longValue());
    }

    public FType forIntRef(IntRef n) {
	Id q = n.getName();
	try {
	    FType result = env.getType(q);
	    return result;
	}
	catch (FortressException p) {
	    throw p.setContext(q, env);
	}
    }

    public FType forIntBinaryOp(IntBinaryOp n) {
	long left = longify(n.getLeft());
	long right = longify(n.getRight());
	try {
	    if (n.getOp().getText().equals("+")) return IntNat.make(Math.addExact(left, right));
	    else if (n.getOp().getText().equals("-")) return IntNat.make(Math.subtractExact(left, right));
	    else if (n.getOp().getText().equals(" ")) return IntNat.make(Math.multiplyExact(left, right));
	    else return bug(n, errorMsg("EvalType: ", n.getClass(), " is not yet implemented."));
	}
	catch (ArithmeticException e) {
	    return error(n, errorMsg("Static argument ", n, " is out of range for a nat parameter, whose values are those of NN32, 0 to 4294967295, and for an int parameter, whose values are those of ZZ32, -2147483648 to 2147483647"));
	}
    }

    public FType defaultCase(Node x) {
	return bug(x, errorMsg("EvalType: ", x.getClass(), " is not a subtype of IntExpr."));
    }
});

